cd /tmp/hwpx_work && python3 -c "
import os
import re

placeholders_found = []
for root, dirs, files in os.walk('template_contents'):
    for f in files:
        filepath = os.path.join(root, f)
        try:
            with open(filepath, 'r', encoding='utf-8') as file:
                content = file.read()
                matches = re.findall(r'\{\{[^}]+\}\}', content)
                for match in matches:
                    placeholders_found.append((filepath, match))
        except Exception as e:
            pass

print('Placeholders found:')
for filepath, placeholder in placeholders_found:
    print(f'  {filepath}: {placeholder}')
"

